import numpy as np
from scipy.optimize import least_squares
coords=np.array([[113.,50.],[182.6,47.],[123.2,127.7],[191.4,109.5],[101.,109.2]])
f=300.;cx=147.2; cy=116.
def points(p):
 D,e,theta,H,df,db,au,av=p
 u=np.array([np.cos(theta),np.sin(theta),0]); q=np.array([-np.sin(theta),np.cos(theta),0]);
 return np.array([u*(-.5+au)+q*av+[0,0,H],u*(.5+au)+q*av+[0,0,H],-u*.5-q*df,u*.5-q*df,-u*.5+q*db])
def get(p):
 D,e=p[:2];pts=points(p)
 z=D+np.cos(e)*pts[:,1]-np.sin(e)*pts[:,2]
 return np.stack([cx+f*pts[:,0]/z,cy+f*(-np.sin(e)*pts[:,1]-np.cos(e)*pts[:,2])/z],1)
def fun(p):return (get(p)-coords).flatten()
r=least_squares(fun,[4,.3,.5,.8,.35,.25,0,0],bounds=([1,.1,0,.3,.1,.1,-.5,-.5],[9,.7,1.4,2,1,1,.5,.5]))
print(r.x);print(get(r.x));print(r.cost)
np.save('.tmp/params.npy',r.x)
PY
python .tmp/fit2.py"
